package com.bank.jvm;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

// Exercises G1 with small churn plus occasional humongous allocations.
public class G1Demo {
    private static final Logger log = Logger.getLogger(G1Demo.class.getName());

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        Logger root = Logger.getLogger("");
        for (Handler old : root.getHandlers()) root.removeHandler(old);
        root.addHandler(h);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        G1Config config = new G1Config();
        config.printG1Settings();

        // Keep a few statement blobs alive briefly to create Old/Humongous pressure.
        Deque<StatementBlob> recentStatements = new ArrayDeque<>();

        for (int i = 0; i < 500_000; i++) {
            // Small short-lived transfer events -> Young regions.
            TransferEvent e = new TransferEvent("TXF-" + i, new BigDecimal("50000"));
            if (e.getAmount().signum() <= 0) log.warning("non-positive amount"); // keeps JIT honest

            // Every 50k iterations, allocate a large statement (Humongous region).
            if (i % 50_000 == 0) {
                StatementBlob blob = new StatementBlob("CORP-" + i, 4 * 1024 * 1024); // 4MB
                recentStatements.addLast(blob);
                if (recentStatements.size() > 3) recentStatements.removeFirst(); // bound memory
                log.info(() -> "Generated corporate statement blob at iteration " + i);
            }
        }
        config.printGcStats();
    }
}

