class StatementBlob {
    private final String clientId; private final byte[] pdfBytes; // large payload
    StatementBlob(String clientId, int sizeBytes) {
        this.clientId = clientId; this.pdfBytes = new byte[sizeBytes];
    }
}

// ─── Would be in G1Config.java in a real project ───
class G1Config {
    private static final Logger log = Logger.getLogger(G1Config.class.getName());

    // Reads G1-relevant VM options via HotSpotDiagnosticMXBean.
    void printG1Settings() {
        try {
            var bean = java.lang.management.ManagementFactory.getPlatformMXBean(
                    com.sun.management.HotSpotDiagnosticMXBean.class);
            log.info("MaxGCPauseMillis = " + bean.getVMOption("MaxGCPauseMillis").getValue());
            log.info("G1HeapRegionSize = " + bean.getVMOption("G1HeapRegionSize").getValue());
            log.info("UseG1GC          = " + bean.getVMOption("UseG1GC").getValue());
        } catch (Exception ex) {
            log.log(Level.SEVERE, "Could not read VM options", ex);
        }
    }

    void printGcStats() {
        for (var gc : java.lang.management.ManagementFactory.getGarbageCollectorMXBeans()) {
            log.info(String.format("Collector %-26s collections=%d totalPause=%dms",
                    gc.getName(), gc.getCollectionCount(), gc.getCollectionTime()));
        }
    }
}
